      if (lookahead == 'r') ADVANCE(46);
      END_STATE();
    case 9:
      if (lookahead == 'a') ADVANCE(47);
      if (lookahead == 'l') ADVANCE(48);
      if (lookahead == 'o') ADVANCE(49);
      END_STATE();
    case 10:
      if (lookahead == 'e') ADVANCE(50);
